const L = span, H = height, n = Math.max(2, Math.round(panels)), y0 = member_size / 2, y1 = y0 + H, p = L / n;
const line = (x0, ya, x1, yb) => addprim(0, 'polyline', [addpoint(0, [x0, ya, 0]), addpoint(0, [x1, yb, 0])]);
const X = (i) => -L / 2 + i * p;
if (layout === 'warren') {
  for (let i = 0; i < n; i++) i % 2 === 0 ? line(X(i), y0, X(i + 1), y1) : line(X(i), y1, X(i + 1), y0);
} else {
  for (let i = 0; i <= n; i++) line(X(i), y0, X(i), y1);
  for (let i = 0; i < n; i++) {
    const left = X(i) + p / 2 < 0;
    const downToMiddle = layout === 'pratt';
    if (left === downToMiddle) line(X(i), y1, X(i + 1), y0); else line(X(i), y0, X(i + 1), y1);
  }
}
